WITH translated(restaurant_id,locale,display_name,short_description,source_notes) AS (VALUES
('dc473b8f-d043-40e5-ad78-5ed7b4195354','ko','히말라야 종각점','서울 종로구 종로8길 5의 인도·네팔 음식 전문점입니다. 공개 지점 메뉴에는 런치 세트, 채식 탈리, 탄두리 요리와 난 등이 있습니다.','https://www.tabling.co.kr/place/677cc7a066de5f0698751174 | https://polle.com/place/34Sc2N/%ED%9E%88%EB%A7%90%EB%9D%BC%EC%95%BC | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('dc473b8f-d043-40e5-ad78-5ed7b4195354','en','Himalaya Jonggak','An Indian and Nepalese restaurant at 5 Jong-ro 8-gil in central Seoul. Its published branch menu includes lunch sets, vegetarian thali, tandoori dishes and naan.','https://www.tabling.co.kr/place/677cc7a066de5f0698751174 | https://polle.com/place/34Sc2N/%ED%9E%88%EB%A7%90%EB%9D%BC%EC%95%BC | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('dc473b8f-d043-40e5-ad78-5ed7b4195354','ja','ヒマラヤ 鍾閣店','ソウル・鍾路8ギル5にあるインド・ネパール料理店。ランチセット、ベジタリアン・ターリー、タンドリー料理、ナンなどがメニューに掲載されています。','https://www.tabling.co.kr/place/677cc7a066de5f0698751174 | https://polle.com/place/34Sc2N/%ED%9E%88%EB%A7%90%EB%9D%BC%EC%95%BC | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('dc473b8f-d043-40e5-ad78-5ed7b4195354','zh-CN','Himalaya 钟阁店','位于首尔钟路8街5号的印度及尼泊尔料理餐厅。公开菜单包括午市套餐、素食塔利、坦都里料理和烤饼等。','https://www.tabling.co.kr/place/677cc7a066de5f0698751174 | https://polle.com/place/34Sc2N/%ED%9E%88%EB%A7%90%EB%9D%BC%EC%95%BC | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('7b9cfbb8-83af-4dd9-93e9-1292eb7fb15b','ko','영화루','서울 종로구 자하문로7길 65에 있는 중식당입니다. 짜장면, 짬뽕, 고추간짜장과 삼선쟁반짜장 등 중식 면 요리가 소개되어 있습니다.','https://www.tabling.co.kr/place/677cc7a166de5f06987511d5 | https://polle.com/place/367IDs/%EC%98%81%ED%99%94%EB%A3%A8 | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('7b9cfbb8-83af-4dd9-93e9-1292eb7fb15b','en','Yeonghwaru','A Chinese restaurant at 65 Jahamun-ro 7-gil in Jongno. The listed noodle dishes include jajangmyeon, jjamppong, spicy gan-jajang and seafood platter jajang.','https://www.tabling.co.kr/place/677cc7a166de5f06987511d5 | https://polle.com/place/367IDs/%EC%98%81%ED%99%94%EB%A3%A8 | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('7b9cfbb8-83af-4dd9-93e9-1292eb7fb15b','ja','ヨンファル','ソウル・鍾路区紫霞門路7ギル65にある中華料理店。ジャージャー麺、チャンポン、唐辛子入りカンジャジャン、海鮮大皿ジャージャー麺などが掲載されています。','https://www.tabling.co.kr/place/677cc7a166de5f06987511d5 | https://polle.com/place/367IDs/%EC%98%81%ED%99%94%EB%A3%A8 | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('7b9cfbb8-83af-4dd9-93e9-1292eb7fb15b','zh-CN','Yeonghwaru','位于首尔钟路区紫霞门路7街65号的中餐馆。公开菜单包括韩式炸酱面、辣海鲜汤面、辣椒干炸酱面及三鲜盘装炸酱面。','https://www.tabling.co.kr/place/677cc7a166de5f06987511d5 | https://polle.com/place/367IDs/%EC%98%81%ED%99%94%EB%A3%A8 | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('29672a47-4a81-403d-bbf6-c8b3481d46d7','ko','된장예술과 술','서울 종로구 삼일대로15길 20의 한식당입니다. 된장정식과 암돼지볶음, 부추전, 북어찜구이, 녹두빈대떡을 공개 메뉴에서 확인할 수 있습니다.','https://www.tabling.co.kr/place/677cc7a166de5f06987511e0 | https://www.diningcode.com/profile.php?rid=HAbodMSg2ugU | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('29672a47-4a81-403d-bbf6-c8b3481d46d7','en','Doenjang Yesulgwa Sul','A Korean restaurant at 20 Samil-daero 15-gil in Jongno. Listed dishes include a soybean-paste set meal, stir-fried pork, chive pancake, grilled dried pollock and mung-bean pancake.','https://www.tabling.co.kr/place/677cc7a166de5f06987511e0 | https://www.diningcode.com/profile.php?rid=HAbodMSg2ugU | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('29672a47-4a81-403d-bbf6-c8b3481d46d7','ja','テンジャン芸術と酒','ソウル・鍾路区三一路15ギル20にある韓国料理店。テンジャン定食、豚肉炒め、ニラチヂミ、干しスケトウダラ、緑豆チヂミなどが紹介されています。','https://www.tabling.co.kr/place/677cc7a166de5f06987511e0 | https://www.diningcode.com/profile.php?rid=HAbodMSg2ugU | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('29672a47-4a81-403d-bbf6-c8b3481d46d7','zh-CN','Doenjang Yesulgwa Sul','位于首尔钟路区三一路15街20号的韩餐厅。菜单包括大酱套餐、炒猪肉、韭菜煎饼、调味烤干明太鱼及绿豆煎饼。','https://www.tabling.co.kr/place/677cc7a166de5f06987511e0 | https://www.diningcode.com/profile.php?rid=HAbodMSg2ugU | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('40044245-014c-420f-8a10-0676d0c67807','ko','진미통닭','서울 종로구 통일로 250의 옛날식 통닭집입니다. 공개 메뉴에는 양념통닭과 통닭, 1인분 치킨, 마른안주와 노가리가 있습니다.','https://www.diningcode.com/profile.php?rid=pnHPNYYQmnb1 | https://www.daangn.com/kr/local-profile/%EC%A7%84%EB%AF%B8%ED%86%B5%EB%8B%AD-1zyefpmr4gpn/ | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('40044245-014c-420f-8a10-0676d0c67807','en','Jinmi Tongdak','An old-style Korean fried-chicken restaurant at 250 Tongil-ro in Jongno. Public menus list seasoned chicken, whole fried chicken, single servings and dried snacks.','https://www.diningcode.com/profile.php?rid=pnHPNYYQmnb1 | https://www.daangn.com/kr/local-profile/%EC%A7%84%EB%AF%B8%ED%86%B5%EB%8B%AD-1zyefpmr4gpn/ | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('40044245-014c-420f-8a10-0676d0c67807','ja','チンミトンダク','ソウル・鍾路区統一路250にある昔ながらの韓国風フライドチキン店。ヤンニョムチキン、丸鶏のチキン、1人前のチキン、乾き物などが紹介されています。','https://www.diningcode.com/profile.php?rid=pnHPNYYQmnb1 | https://www.daangn.com/kr/local-profile/%EC%A7%84%EB%AF%B8%ED%86%B5%EB%8B%AD-1zyefpmr4gpn/ | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('40044245-014c-420f-8a10-0676d0c67807','zh-CN','Jinmi Tongdak','位于首尔钟路区统一路250号的传统韩式炸鸡店。公开菜单包括甜辣炸鸡、整只炸鸡、单人份炸鸡以及干制下酒菜。','https://www.diningcode.com/profile.php?rid=pnHPNYYQmnb1 | https://www.daangn.com/kr/local-profile/%EC%A7%84%EB%AF%B8%ED%86%B5%EB%8B%AD-1zyefpmr4gpn/ | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('ced7b371-6cd0-4589-ab48-ce6a5881e520','ko','모던김밥','서울 종로구 자하문로2길 10에 있는 김밥·분식집입니다. 모던김밥, 치즈김밥, 참치김밥, 소고기김밥과 계란라면이 소개되어 있습니다.','https://www.tabling.co.kr/place/677ccaa766de5f06987bafa4 | https://polle.com/place/1tEd1Z/%EB%AA%A8%EB%8D%98%EA%B9%80%EB%B0%A5 | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('ced7b371-6cd0-4589-ab48-ce6a5881e520','en','Modern Gimbap','A Korean gimbap and casual snack restaurant at 10 Jahamun-ro 2-gil in Jongno. The menu lists its signature gimbap, cheese, tuna and beef rolls, plus egg ramen.','https://www.tabling.co.kr/place/677ccaa766de5f06987bafa4 | https://polle.com/place/1tEd1Z/%EB%AA%A8%EB%8D%98%EA%B9%80%EB%B0%A5 | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('ced7b371-6cd0-4589-ab48-ce6a5881e520','ja','モダンキンパ','ソウル・鍾路区紫霞門路2ギル10にあるキンパと軽食の店。看板キンパ、チーズ、ツナ、牛肉のキンパ、卵ラーメンがメニューに掲載されています。','https://www.tabling.co.kr/place/677ccaa766de5f06987bafa4 | https://polle.com/place/1tEd1Z/%EB%AA%A8%EB%8D%98%EA%B9%80%EB%B0%A5 | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('ced7b371-6cd0-4589-ab48-ce6a5881e520','zh-CN','Modern Gimbap','位于首尔钟路区紫霞门路2街10号的紫菜包饭与韩式小吃店。菜单包括招牌包饭、芝士包饭、金枪鱼包饭、牛肉包饭和鸡蛋方便面。','https://www.tabling.co.kr/place/677ccaa766de5f06987bafa4 | https://polle.com/place/1tEd1Z/%EB%AA%A8%EB%8D%98%EA%B9%80%EB%B0%A5 | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('2db318a0-d504-4e2e-bf3e-c75d629b2418','ko','카페 레이어드 안국점','서울 종로구 북촌로2길 2-3에 있는 디저트 카페입니다. 공개 메뉴에는 시그니처 스콘, 홈메이드 스콘, 미니 케이크와 커피가 안내되어 있습니다.','https://www.tabling.co.kr/place/677ccb5566de5f06987d0c86 | https://polle.com/place/3e2GVz/%EC%B9%B4%ED%8E%98%20%EB%A0%88%EC%9D%B4%EC%96%B4%EB%93%9C | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('2db318a0-d504-4e2e-bf3e-c75d629b2418','en','Cafe Layered Anguk','A dessert café at 2-3 Bukchon-ro 2-gil in Jongno, Seoul. Branch menus feature signature and homemade scones, mini cakes and coffee.','https://www.tabling.co.kr/place/677ccb5566de5f06987d0c86 | https://polle.com/place/3e2GVz/%EC%B9%B4%ED%8E%98%20%EB%A0%88%EC%9D%B4%EC%96%B4%EB%93%9C | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('2db318a0-d504-4e2e-bf3e-c75d629b2418','ja','カフェ・レイヤード 安国店','ソウル・鍾路区北村路2ギル2-3にあるデザートカフェ。シグネチャースコーン、自家製スコーン、ミニケーキ、コーヒーなどが紹介されています。','https://www.tabling.co.kr/place/677ccb5566de5f06987d0c86 | https://polle.com/place/3e2GVz/%EC%B9%B4%ED%8E%98%20%EB%A0%88%EC%9D%B4%EC%96%B4%EB%93%9C | editorial 4-locale branch review 2026-10-14; prices snapshots'),
('2db318a0-d504-4e2e-bf3e-c75d629b2418','zh-CN','Cafe Layered 安国店','位于首尔钟路区北村路2街2-3号的甜点咖啡馆。公开菜单包含招牌司康、手工司康、迷你蛋糕及咖啡。','https://www.tabling.co.kr/place/677ccb5566de5f06987d0c86 | https://polle.com/place/3e2GVz/%EC%B9%B4%ED%8E%98%20%EB%A0%88%EC%9D%B4%EC%96%B4%EB%93%9C | editorial 4-locale branch review 2026-10-14; prices snapshots')
)
UPDATE restaurant_localizations loc SET display_name=t.display_name,short_description=t.short_description,
 source_notes=t.source_notes,publication_state='review',updated_at=now()
FROM translated t WHERE loc.restaurant_id=t.restaurant_id::uuid AND loc.locale=t.locale
AND loc.publication_state='draft'
AND loc.source_notes LIKE 'release300:2026-10-14:public-permit-district-only%';
